create or replace function public.sales_charge_catalog_list_v610(p_tenant_id uuid,p_location_id uuid,p_device_id uuid,p_active_only boolean default true) returns jsonb language plpgsql stable security definer set search_path=public,private,pg_temp as $$ declare v_rows jsonb; begin perform private.erp_validate_vertical_device_scope(p_tenant_id,p_location_id,p_device_id,'restaurant','view'); if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied'; end if; select coalesce(jsonb_agg(jsonb_build_object('id',c.id,'code',c.code,'name',c.name,'charge_kind',c.charge_kind,'service_variant_id',c.service_variant_id,'default_quantity',c.default_quantity,'auto_apply_dine_in',c.auto_apply_dine_in,'auto_apply_takeaway',c.auto_apply_takeaway,'auto_apply_delivery',c.auto_apply_delivery,'active',c.active,'product_name',p.name,'variant_name',pv.name,'sku',pv.sku,'selling_price',pv.selling_price,'tax_rate',p.tax_rate,'tax_code',p.tax_code) order by c.name,c.code),'[]'::jsonb) into v_rows from public.sales_charge_catalog_v610 c join public.product_variants pv on pv.id=c.service_variant_id and pv.tenant_id=c.tenant_id join public.products p on p.id=pv.product_id and p.tenant_id=pv.tenant_id where c.tenant_id=p_tenant_id and (not p_active_only or c.active); return jsonb_build_object('charges',v_rows); end; $$;;
